create extension if not exists pgcrypto;
create type public.user_role as enum ('subscriber','admin');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role public.user_role not null default 'subscriber', created_at timestamptz not null default now());
create table public.charities (id uuid primary key default gen_random_uuid(), name text not null, description text not null, image_url text, featured boolean not null default false, active boolean not null default true, created_at timestamptz not null default now());
create table public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, plan text not null check (plan in ('monthly','yearly')), status text not null default 'inactive', renewal_date date, stripe_customer_id text, stripe_subscription_id text, created_at timestamptz not null default now());
create table public.user_preferences (user_id uuid primary key references public.profiles(id) on delete cascade, charity_id uuid references public.charities(id) on delete set null, charity_percent integer not null default 10 check (charity_percent between 10 and 100));
create table public.golf_scores (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, score integer not null check (score between 1 and 45), score_date date not null, created_at timestamptz not null default now(), unique(user_id,score_date));
create table public.draws (id uuid primary key default gen_random_uuid(), month date not null unique, draw_type text not null check (draw_type in ('random','algorithmic')), status text not null default 'draft', seed text, published_at timestamptz, created_at timestamptz not null default now());
create table public.draw_results (id uuid primary key default gen_random_uuid(), draw_id uuid not null references public.draws(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, matched_numbers integer not null check (matched_numbers in (3,4,5)), prize_amount numeric(12,2) not null default 0, winner_status text not null default 'pending', proof_url text, paid_at timestamptz);
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index golf_scores_user_date_idx on public.golf_scores(user_id,score_date desc);
create index draw_results_draw_idx on public.draw_results(draw_id);
create index audit_logs_entity_idx on public.audit_logs(entity_type,entity_id,created_at desc);